import java.util.Scanner;

public class Main {
    public static int solve(int n, int mod) {
        if (n <= 3) {
            return 0;
        }
        int last_result = 17;
        int result = 17;
        int max_size = (n - 1) * (n - 2) / 2 + 1;
        int toggle = 1;
        int[][] rec = new int[2][max_size + 1];
        rec[0][0] = 1;
        rec[0][1] = 2;
        rec[0][2] = 2;
        rec[0][3] = 1;
        for (int m = 4; m < n; m++) {
            int total_pairs = m * (m - 1) / 2;
            result = (m + 1) * last_result;
            int partial_sum = 0;
            for (int i = 0; i < m; i++) {
                partial_sum += rec[toggle ^ 1][i];
                rec[toggle][i] = partial_sum % mod;
            }
            for (int i = m; i <= total_pairs / 2; i++) {
                partial_sum += rec[toggle ^ 1][i];
                partial_sum -= rec[toggle ^ 1][i - m];
                rec[toggle][i] = partial_sum % mod;
            }
            for (int i = 0; i <= total_pairs / 2; i++) {
                rec[toggle][total_pairs - i] = rec[toggle][i];
            }
            int total = 0;
            for (int i = 0; i < total_pairs; i++) {
                int temp_sum = 0;
                int start_idx = Math.max(1, -total_pairs + i + m + 2);
                for (int j = start_idx; j <= m; j++) {
                    int index = m + 2 - j + i;
                    if (index >= 0 && index <= total_pairs) {
                        temp_sum += j * rec[toggle][index];
                    }
                }
                total += rec[toggle][i];
                total %= mod;
                temp_sum %= mod;
                result += (temp_sum * total) % mod;
                result %= mod;
            }
            last_result = result;
            toggle ^= 1;
        }
        return result % mod;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        System.out.println(solve(n, mod));
        scanner.close();
    }
}
